package com.college.events.controller;
import com.college.events.model.EventScheduleChange; import com.college.events.repository.EventScheduleChangeRepository; import com.college.events.repository.RegistrationRepository; import com.college.events.security.DomainAccess; import lombok.RequiredArgsConstructor; import org.springframework.http.CacheControl; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/cujammu/disruptions") @RequiredArgsConstructor
public class DisruptionApiController { private final DomainAccess access; private final RegistrationRepository registrations; private final EventScheduleChangeRepository changes;
 @GetMapping("/mine") public ResponseEntity<?> mine(){List<Map<String,Object>> out=new ArrayList<>(); registrations.findByUserOrderByRegisteredAtDesc(access.currentUser()).stream().limit(100).forEach(r->changes.findByEventIdOrderByChangeNumberAsc(r.getEvent().getId()).forEach(c->{Map<String,Object> v=new LinkedHashMap<>();v.put("eventId",r.getEvent().getId());v.put("eventTitle",r.getEvent().getTitle());v.put("changeType",c.getChangeType());v.put("reason",c.getPublicReason());v.put("previousDate",c.getPreviousDate());v.put("replacementDate",c.getReplacementDate());v.put("recordedAt",c.getRecordedAt());out.add(v);}));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(out);}
}
